"""
Module to define the determination os  the syslog log files for the keyword "Get Log File".
"""
import tarfile
import os


class CloudGnbSyslogLogfileProvider:
    """Concrete implementation to determine the location of the packed syslog archive, unzip its log files and
    provide the list of all included log files as returned value.
    """

    def get_syslog_log_file(self, log_directory, collector_config):
        """Function to provide the log files based on the network_element and target_dir. The correct
        collector is determined in the collector configuration to get the path where the log file was storred
        by "collect collectors". Knowing the resulting filename, this tgz file is taken to unpack the containing
        syslogs and return the full paths to those log files.

        :param str log_directory: the path where the log files of the collector are stored
        :param str collector_config: the collector configuration of the collector to obtain additional information
        """
        all_log_files = []
        for sub_collector in collector_config['members']:
            sub_directory = os.path.join(log_directory, sub_collector)
            tgz_file = os.path.join(sub_directory, 'kubernetes_log.tgz')

            with tarfile.open(tgz_file, 'r:gz') as unpack_tgz_file:
                unpack_tgz_file.extractall(path=sub_directory)

            all_log_files += [os.path.join(sub_directory, filename) for filename in os.listdir(sub_directory)
                              if filename.lower().endswith('log')]

        return all_log_files
